-- The LMS module's tables, for MySQL 8.0.4+ (or MariaDB 10.6+).
--
-- Every table is prefixed `lms_` so this can be applied to a database that
-- already has an application in it. Idempotent throughout, so it is safe to
-- run from a boot hook rather than a separate release step.
--
-- TWO THINGS TO CHECK BEFORE APPLYING.
--
-- 1. The host's user table. This copy is wired to Kingdom Connections'
--    `contacts` table (church members — the same people the mobile API
--    syncs), not `users` (internal staff accounts). Three columns carry that
--    id:
--
--      lms_cohort_members.user_id
--      lms_lesson_progress.user_id
--      lms_quiz_attempts.user_id
--
--    `contacts.id` is `int unsigned auto_increment`, not a 36-character
--    UUID, so these are `varchar(20)` here rather than `char(36)` — plenty
--    for any such id, stored as a string since the module never parses it.
--    MySQL will not let a `varchar` column carry a real `foreign key`
--    constraint against an `int unsigned` one (incompatible types), so
--    there is an index for lookup speed but no DB-enforced FK and no
--    `on delete cascade` — the host application is responsible for only
--    ever writing an id that exists in `contacts`. This CRM already never
--    hard-deletes a contact row (donation/membership history must be
--    retained), so the cascade case this would otherwise cover does not
--    arise in practice. A staff account acting as instructor or admin
--    resolves through its own `users.contact_id` link rather than getting a
--    second identity scheme here.
--
-- 2. **The connection must be in UTC.** MySQL's `TIMESTAMP` converts to and
--    from the session's time zone, so a connection in any other zone reads
--    back a different instant than it wrote. For mysql2 that is
--    `timezone: 'Z'`. This is not a preference: it is the difference between
--    a course release date that opens a course when it should and one that
--    opens it hours early, with nothing in the data to show why.
--
-- Three notes on how this differs from the Postgres migration, each of which
-- is a MySQL constraint rather than a choice:
--
--   * Keys are `char(36)` holding a text UUID, generated by the application.
--     MySQL has no `uuid` type, no usable random default, and — unlike
--     MariaDB — no `RETURNING`, so the id cannot be read back from an insert.
--   * Columns carrying an index are `varchar` with a length, because InnoDB
--     will not index a `text` column without a prefix. 191 keeps a `utf8mb4`
--     key under the 767-byte limit of older row formats.
--   * `json` rather than `jsonb`, and `JSON_CONTAINS`/`JSON_TABLE` rather
--     than `@>`/`jsonb_array_elements_text`.

create table if not exists lms_cohorts (
  id          char(36)     not null,
  name        varchar(191) not null,
  slug        varchar(191) not null,
  description text,
  status      enum('planned', 'active', 'archived') not null default 'planned',
  starts_on   timestamp(3) null,
  ends_on     timestamp(3) null,
  created_at  timestamp(3) not null default current_timestamp(3),
  updated_at  timestamp(3) not null default current_timestamp(3),
  primary key (id),
  unique key lms_cohorts_slug_key (slug)
) engine = innodb default charset = utf8mb4;

create table if not exists lms_cohort_members (
  cohort_id char(36)      not null,
  user_id   varchar(20)   not null,
  joined_at timestamp(3) not null default current_timestamp(3),
  primary key (cohort_id, user_id),
  key lms_cohort_members_user_idx (user_id),
  constraint lms_cohort_members_cohort_fk foreign key (cohort_id) references lms_cohorts (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_courses (
  id                char(36)     not null,
  slug              varchar(191) not null,
  title             varchar(255) not null,
  subtitle          varchar(500),
  summary           text,
  description       text,
  cover_image_url   varchar(1000),
  status            enum('draft', 'published', 'archived') not null default 'draft',
  estimated_minutes int,
  level             enum('foundation', 'intermediate', 'advanced') not null default 'foundation',
  language          varchar(100) not null default 'English',
  audience          text,
  outcomes          json not null,
  prerequisites     json not null,
  topics            json not null,
  created_by        varchar(20),
  created_at        timestamp(3) not null default current_timestamp(3),
  updated_at        timestamp(3) not null default current_timestamp(3),
  primary key (id),
  unique key lms_courses_slug_key (slug),
  key lms_courses_status_idx (status),
  key lms_courses_title_idx (title)
) engine = innodb default charset = utf8mb4;

-- The entitlement edge. A learner reaches a course only through a row here.
create table if not exists lms_cohort_courses (
  cohort_id      char(36) not null,
  course_id      char(36) not null,
  available_from timestamp(3) null,
  position       int not null default 0,
  primary key (cohort_id, course_id),
  key lms_cohort_courses_course_idx (course_id),
  constraint lms_cohort_courses_cohort_fk foreign key (cohort_id) references lms_cohorts (id) on delete cascade,
  constraint lms_cohort_courses_course_fk foreign key (course_id) references lms_courses (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_modules (
  id         char(36)     not null,
  course_id  char(36)     not null,
  title      varchar(255) not null,
  summary    text,
  position   int not null default 0,
  created_at timestamp(3) not null default current_timestamp(3),
  updated_at timestamp(3) not null default current_timestamp(3),
  primary key (id),
  key lms_modules_course_idx (course_id, position),
  constraint lms_modules_course_fk foreign key (course_id) references lms_courses (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_lessons (
  id                     char(36)     not null,
  module_id              char(36)     not null,
  slug                   varchar(191) not null,
  title                  varchar(255) not null,
  summary                text,
  kind                   enum('video', 'reading', 'assignment') not null default 'video',
  body                   text,
  body_format            enum('html', 'markdown') not null default 'markdown',
  key_points             json not null,
  reflection_questions   json not null,
  estimated_minutes      int,
  video_ref              varchar(191),
  video_status           enum('none', 'uploading', 'processing', 'ready', 'error') not null default 'none',
  video_duration_seconds int,
  video_thumbnail_url    varchar(1000),
  position               int not null default 0,
  is_published           boolean not null default false,
  created_at             timestamp(3) not null default current_timestamp(3),
  updated_at             timestamp(3) not null default current_timestamp(3),
  primary key (id),
  key lms_lessons_module_idx (module_id, position),
  unique key lms_lessons_module_slug_key (module_id, slug),
  -- Video callbacks arrive keyed by the provider's own reference.
  key lms_lessons_video_ref_idx (video_ref),
  constraint lms_lessons_module_fk foreign key (module_id) references lms_modules (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_lesson_attachments (
  id           char(36)     not null,
  lesson_id    char(36)     not null,
  label        varchar(191) not null,
  object_key   varchar(500) not null,
  content_type varchar(191),
  size_bytes   int,
  created_at   timestamp(3) not null default current_timestamp(3),
  primary key (id),
  key lms_lesson_attachments_lesson_idx (lesson_id),
  constraint lms_lesson_attachments_lesson_fk foreign key (lesson_id) references lms_lessons (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_lesson_progress (
  user_id               varchar(20) not null,
  lesson_id             char(36) not null,
  status                enum('in_progress', 'completed') not null default 'in_progress',
  seconds_watched       int not null default 0,
  last_position_seconds int not null default 0,
  completed_at          timestamp(3) null,
  updated_at            timestamp(3) not null default current_timestamp(3),
  primary key (user_id, lesson_id),
  key lms_lesson_progress_lesson_idx (lesson_id),
  constraint lms_lesson_progress_lesson_fk foreign key (lesson_id) references lms_lessons (id)  on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_quizzes (
  id            char(36)     not null,
  lesson_id     char(36)     not null,
  title         varchar(255) not null,
  instructions  text,
  passing_score int not null default 80,
  max_attempts  int not null default 3,
  created_at    timestamp(3) not null default current_timestamp(3),
  updated_at    timestamp(3) not null default current_timestamp(3),
  primary key (id),
  unique key lms_quizzes_lesson_key (lesson_id),
  constraint lms_quizzes_lesson_fk foreign key (lesson_id) references lms_lessons (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_quiz_questions (
  id          char(36) not null,
  quiz_id     char(36) not null,
  prompt      text not null,
  explanation text,
  position    int not null default 0,
  primary key (id),
  key lms_quiz_questions_quiz_idx (quiz_id, position),
  constraint lms_quiz_questions_quiz_fk foreign key (quiz_id) references lms_quizzes (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_quiz_options (
  id          char(36) not null,
  question_id char(36) not null,
  label       text not null,
  is_correct  boolean not null default false,
  position    int not null default 0,
  primary key (id),
  key lms_quiz_options_question_idx (question_id, position),
  constraint lms_quiz_options_question_fk foreign key (question_id) references lms_quiz_questions (id) on delete cascade
) engine = innodb default charset = utf8mb4;

create table if not exists lms_quiz_attempts (
  id           char(36) not null,
  quiz_id      char(36) not null,
  user_id      varchar(20) not null,
  score        int not null,
  passed       boolean not null,
  answers      json not null,
  submitted_at timestamp(3) not null default current_timestamp(3),
  primary key (id),
  key lms_quiz_attempts_user_idx (user_id, quiz_id),
  constraint lms_quiz_attempts_quiz_fk foreign key (quiz_id) references lms_quizzes (id) on delete cascade
) engine = innodb default charset = utf8mb4;
